:root {
  --color-primary: #8B4973;
  --color-primary-dark: #6B3859;
  --color-accent: #D4A5B8;
  --color-accent-light: #E8D4E0;
  --color-accent-on-dark: #F0E0E8;
  --color-text: #333333;
  --color-text-light: #666666;
  --color-background: #FFFFFF;
  --color-border: #E0D0D8;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: "Trebuchet MS", Verdana, sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --container-padding: 1.5rem;
  --container-max-width: 1000px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-background);
}

.container {
  max-width: var(--container-max-width);
  margin: 0 auto;
  padding: 0 var(--container-padding);
}

/* Header and Navigation */
.site-header {
  background-color: var(--color-background);
  border-bottom: 3px solid var(--color-primary);
  padding: var(--spacing-lg) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-md);
}

.logo {
  font-family: "Brush Script MT", "Segoe Script", cursive;
  font-size: clamp(1.5rem, 5vw, 2.5rem);
  font-weight: 400;
  color: var(--color-primary-dark);
  text-decoration: none;
  text-shadow: 2px 2px 4px rgba(107, 56, 89, 0.2);
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  transition: color 0.3s ease;
}

.logo:hover {
  color: var(--color-primary);
}

.logo:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 4px;
}

nav[aria-label="Κύρια"] {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
}

nav[aria-label="Κύρια"] a {
  color: var(--color-text);
  text-decoration: none;
  font-weight: 600;
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: 4px;
  transition: all 0.3s ease;
}

nav[aria-label="Κύρια"] a:hover {
  background-color: var(--color-accent-light);
  color: var(--color-primary-dark);
}

nav[aria-label="Κύρια"] a:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 4px;
}

/* Footer */
.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xl) 0 var(--spacing-lg) 0;
  margin-top: var(--spacing-xl);
}

.footer-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
}

.footer-section h3 {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-sm);
  color: var(--color-accent-light);
}

.footer-section p {
  font-size: 0.95rem;
  line-height: 1.8;
  margin-bottom: var(--spacing-xs);
}

.footer-bottom {
  border-top: 1px solid rgba(240, 224, 232, 0.3);
  padding-top: var(--spacing-md);
  text-align: center;
  font-size: 0.9rem;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

h1 {
  font-size: clamp(2rem, 6vw, 3.5rem);
  line-height: 1.2;
}

h2 {
  font-size: 2rem;
  line-height: 1.3;
}

h3 {
  font-size: 1.5rem;
}

p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text-light);
}

/* Links */
a {
  color: var(--color-primary);
  text-decoration: underline;
  transition: all 0.3s ease;
}

a:hover {
  color: var(--color-primary-dark);
}

a:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Buttons */
button, .button, input[type="submit"], input[type="button"], input[type="reset"] {
  background-color: var(--color-primary-dark);
  color: var(--color-background);
  border: none;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: 1rem;
  font-family: var(--font-sans);
  border-radius: 6px;
  cursor: pointer;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  transition: all 0.3s ease;
  font-weight: 600;
}

button:hover, .button:hover, input[type="submit"]:hover, input[type="button"]:hover, input[type="reset"]:hover {
  background-color: var(--color-primary);
  transform: translateY(-2px);
  box-shadow: 0 4px 8px rgba(107, 56, 89, 0.3);
}

button:focus, .button:focus, input[type="submit"]:focus, input[type="button"]:focus, input[type="reset"]:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

button:active, .button:active, input[type="submit"]:active, input[type="button"]:active, input[type="reset"]:active {
  transform: translateY(0);
}

/* Forms */
form {
  max-width: 600px;
  margin: var(--spacing-lg) 0;
}

label {
  display: block;
  margin-bottom: var(--spacing-sm);
  font-weight: 600;
  color: var(--color-text);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="date"],
input[type="time"],
select,
textarea {
  width: 100%;
  padding: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: var(--color-background);
  transition: border-color 0.3s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="date"]:focus,
input[type="time"]:focus,
select:focus,
textarea:focus {
  border-color: var(--color-primary);
  outline: none;
  box-shadow: 0 0 0 3px rgba(139, 73, 115, 0.1);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

/* Cards */
.card {
  background-color: var(--color-background);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  transition: all 0.3s ease;
}

.card:hover {
  border-color: var(--color-primary);
  box-shadow: 0 4px 12px rgba(139, 73, 115, 0.15);
}

/* Grid Helper */
.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-2 {
  grid-template-columns: 1fr;
}

.grid-3 {
  grid-template-columns: 1fr;
}

/* Sections */
section {
  padding: var(--spacing-xl) 0;
}

section:nth-child(even) {
  background-color: var(--color-accent-light);
}

/* Mobile Breakpoint */
@media (max-width: 600px) {
  :root {
    --container-padding: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
  }

  .site-header {
    padding: var(--spacing-md) 0;
  }

  .site-header .container {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-md);
  }

  nav[aria-label="Κύρια"] {
    width: 100%;
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  nav[aria-label="Κύρια"] a {
    display: block;
    padding: var(--spacing-sm) var(--spacing-md);
    background-color: var(--color-accent-light);
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  .grid-2,
  .grid-3 {
    grid-template-columns: 1fr;
  }

  .footer-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  button, .button, input[type="submit"], input[type="button"], input[type="reset"] {
    width: 100%;
  }
}

/* Desktop Breakpoint */
@media (min-width: 601px) {
  .grid-2 {
    grid-template-columns: 1fr 1fr;
  }

  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }

  nav[aria-label="Κύρια"] {
    gap: var(--spacing-lg);
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

