.index-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.index-hero h1 {
  color: var(--color-accent-light);
  margin-bottom: var(--spacing-sm);
}

.index-hero-tagline {
  font-size: 1.5rem;
  font-family: var(--font-serif);
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-md);
  font-weight: 300;
}

.index-hero-description {
  font-size: 1.1rem;
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.index-hero-button {
  background-color: var(--color-accent-light);
  color: var(--color-primary-dark);
  font-weight: 700;
}

.index-hero-button:hover {
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
}

.index-services {
  background-color: var(--color-background);
}

.index-service-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.index-service-card p {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-sm);
}

.index-service-price {
  color: var(--color-primary);
  font-size: 1.2rem;
  margin-top: var(--spacing-md);
}

.index-testimonials {
  background-color: var(--color-accent-light);
}

.index-testimonials h2 {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.index-testimonial-card {
  background-color: var(--color-background);
}

.index-testimonial-stars {
  color: #FFB800;
  font-size: 1.2rem;
  margin-bottom: var(--spacing-sm);
  letter-spacing: 2px;
}

.index-testimonial-text {
  font-style: italic;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
  line-height: 1.8;
}

.index-testimonial-author {
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0;
}

.index-cta {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.index-cta h2 {
  color: var(--color-accent-light);
}

.index-cta p {
  color: var(--color-accent-on-dark);
  font-size: 1.1rem;
  margin-bottom: var(--spacing-lg);
}

.index-cta-button {
  background-color: var(--color-accent-light);
  color: var(--color-primary-dark);
  font-weight: 700;
}

.index-cta-button:hover {
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) 0;
  }

  .index-hero-tagline {
    font-size: 1.2rem;
  }

  .index-hero-description {
    font-size: 1rem;
  }

  .index-hero-button {
    width: 100%;
  }

  .index-cta-button {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-xl) 0;
  }
}

.booking-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.booking-hero h1 {
  color: var(--color-accent-light);
  margin-bottom: var(--spacing-md);
}

.booking-hero p {
  color: var(--color-accent-on-dark);
  font-size: 1.1rem;
}

.booking-services {
  margin-bottom: var(--spacing-lg);
}

.booking-service-card {
  background-color: var(--color-background);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  text-align: center;
  transition: all 0.3s ease;
}

.booking-service-card:hover {
  border-color: var(--color-primary);
  box-shadow: 0 4px 12px rgba(139, 73, 115, 0.15);
  transform: translateY(-4px);
}

.booking-service-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.booking-price {
  font-size: 1.8rem;
  font-weight: bold;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.booking-duration {
  font-size: 0.9rem;
  color: var(--color-text-light);
  font-style: italic;
}

.booking-form-section {
  background-color: var(--color-accent-light);
}

.booking-form {
  max-width: 600px;
  margin: var(--spacing-lg) auto;
}

.booking-fieldset {
  border: none;
  padding: 0 0 var(--spacing-lg) 0;
  margin-bottom: var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}

.booking-fieldset:last-of-type {
  border-bottom: none;
}

.booking-fieldset legend {
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
  font-size: 1.1rem;
  display: block;
}

.booking-form label {
  display: block;
  margin-bottom: var(--spacing-sm);
  font-weight: 600;
  color: var(--color-text);
}

.booking-form input,
.booking-form select,
.booking-form textarea {
  width: 100%;
  padding: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: var(--color-background);
  transition: border-color 0.3s ease;
}

.booking-form input:focus,
.booking-form select:focus,
.booking-form textarea:focus {
  border-color: var(--color-primary);
  outline: none;
  box-shadow: 0 0 0 3px rgba(139, 73, 115, 0.1);
}

.booking-form textarea {
  resize: vertical;
  min-height: 100px;
}

.booking-help-text {
  font-size: 0.85rem;
  color: var(--color-text-light);
  font-style: italic;
  margin-top: calc(var(--spacing-md) * -0.75);
  margin-bottom: var(--spacing-md);
}

.booking-terms {
  margin-bottom: var(--spacing-lg);
  padding: var(--spacing-md);
  background-color: rgba(139, 73, 115, 0.05);
  border-radius: 6px;
}

.booking-terms-label {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-sm);
  margin-bottom: 0;
  font-weight: 600;
  cursor: pointer;
}

.booking-terms-label input[type="checkbox"] {
  width: 20px;
  height: 20px;
  min-width: 20px;
  margin-top: 2px;
  cursor: pointer;
}

.booking-submit {
  width: 100%;
  min-height: 50px;
  font-size: 1.1rem;
  font-weight: 700;
}

.booking-confirmation-text {
  text-align: center;
  font-size: 0.9rem;
  color: var(--color-text-light);
  margin-top: var(--spacing-md);
}

.booking-info-grid {
  gap: var(--spacing-lg);
}

.booking-info-card {
  background-color: var(--color-background);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
}

.booking-info-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.booking-info-list {
  list-style: none;
  padding: 0;
}

.booking-info-list li {
  padding: var(--spacing-sm) 0;
  color: var(--color-text-light);
  border-bottom: 1px solid var(--color-border);
}

.booking-info-list li:last-child {
  border-bottom: none;
}

.booking-info-list a {
  color: var(--color-primary);
  text-decoration: none;
  font-weight: 600;
}

.booking-info-list a:hover {
  text-decoration: underline;
}

@media (max-width: 600px) {
  .booking-hero {
    padding: var(--spacing-lg) 0;
  }

  .booking-hero h1 {
    font-size: 1.75rem;
  }

  .booking-hero p {
    font-size: 1rem;
  }

  .booking-services {
    grid-template-columns: 1fr;
  }

  .booking-service-card {
    padding: var(--spacing-md);
  }

  .booking-price {
    font-size: 1.5rem;
  }

  .booking-form {
    margin: var(--spacing-md) auto;
  }

  .booking-fieldset {
    padding-bottom: var(--spacing-md);
    margin-bottom: var(--spacing-md);
  }

  .booking-submit {
    font-size: 1rem;
  }

  .booking-info-grid {
    grid-template-columns: 1fr;
  }
}

@media (min-width: 601px) {
  .booking-services {
    grid-template-columns: repeat(3, 1fr);
  }

  .booking-info-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.about-hero {
  background: linear-gradient(135deg, var(--color-accent-light) 0%, var(--color-accent) 100%);
  padding: var(--spacing-xl) 0;
  margin-bottom: 0;
}

.about-hero h1 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.about-intro {
  font-size: 1.2rem;
  color: var(--color-text);
  max-width: 700px;
  line-height: 1.8;
}

.about-story {
  background-color: var(--color-background);
}

.about-story p {
  max-width: 800px;
  font-size: 1.05rem;
  line-height: 1.8;
  margin-bottom: var(--spacing-lg);
}

.values-grid {
  margin-top: var(--spacing-lg);
}

.value-card {
  background-color: var(--color-background);
}

.value-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
  font-size: 1.3rem;
}

.value-card p {
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--color-text-light);
}

.team-grid {
  margin-top: var(--spacing-lg);
}

.team-member {
  text-align: center;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.team-member:hover {
  transform: translateY(-4px);
}

.team-photo {
  width: 100%;
  height: 250px;
  object-fit: cover;
  border-radius: 8px;
  margin-bottom: var(--spacing-md);
  display: block;
}

.team-member h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-xs);
  font-size: 1.3rem;
}

.team-role {
  font-size: 0.95rem;
  color: var(--color-primary);
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
}

.team-member p:last-child {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--color-text-light);
}

.about-cta {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  text-align: center;
  padding: var(--spacing-xl) 0;
}

.about-cta h2 {
  color: var(--color-accent-light);
}

.about-cta p {
  color: var(--color-accent-on-dark);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
  font-size: 1.05rem;
}

.about-cta .button {
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
  font-weight: 600;
  margin-top: var(--spacing-md);
}

.about-cta .button:hover {
  background-color: var(--color-accent-light);
}

@media (max-width: 600px) {
  .about-hero {
    padding: var(--spacing-lg) 0;
  }

  .about-intro {
    font-size: 1rem;
  }

  .about-story p {
    font-size: 1rem;
  }

  .team-photo {
    height: 200px;
  }

  .team-member h3 {
    font-size: 1.1rem;
  }

  .about-cta {
    padding: var(--spacing-lg) 0;
  }

  .about-cta .button {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .about-team p:first-of-type {
    margin-bottom: var(--spacing-xl);
  }
}

